#!/usr/bin/env python3
"""fix_act_2_engine.py -- Three-Act Evolution, part 2 of 5: engine + AI.

Needs fix_act_1_data.py first. Adds the Act card engine (evolve in place,
plot points, the Act III gate, KO/revive handling, deck building, deck codes)
and the AI's evolve step. Every edit is anchor-verified (exactly one match)
before anything is written. Additive only. Refuses to run twice.
Writes src/game.src.html.bak. Run from the repo root.
"""
import os, shutil, sys
SRC="src/game.src.html"
MARK="/* ---------------- THREE-ACT EVOLUTION (Act cards) ----------------"
ENGINE='/* ---------------- THREE-ACT EVOLUTION (Act cards) ----------------\n   An Act card is a character card by the rules (it counts against the\n   character limit) but carries cat:\'act\' in code, so every Drawn Mode path\n   keyed on cat:\'char\' (seeding, mulligan counts, can-still-field) ignores it\n   without needing a guard. Evolving rewrites the character object IN PLACE:\n   id stays the Act I id, so anything keyed on identity still sees Macbeth. */\nconst ACT_ALLOW_1E=false;\nfunction actById(id){ return (DATA.acts||[]).find(function(a){ return a.id===id; })||null; }\nfunction actsForDeck(k){ return (DATA.acts||[]).filter(function(a){ return a.deck===k; }); }\nfunction actStageId(c){ return c ? (c._actId||c.id) : null; }\nfunction actStageName(id){ const a=actById(id); if(a) return a.name;\n  for(const k in DATA.characters){ const c=(DATA.characters[k]||[]).find(function(x){ return x.id===id; }); if(c) return c.name; } return id; }\nfunction actBaseOk(c){ return !!c && !c.cid && !c._boss && !c._pmCmd && (ACT_ALLOW_1E || !c.fe); }\nfunction actTurnKey(){ return (S&&S._turnNo)||0; }\nfunction actCanEvolve(c,a){\n  if(!c||c.hp<=0) return {ok:false,why:\'That character is knocked out.\'};\n  if(actStageId(c)!==a.from) return {ok:false,why:a.name+\' evolves from \'+actStageName(a.from)+\'.\'};\n  if((c.turnsInPlay||0)<1) return {ok:false,why:c.name+\' entered play this turn \\u2014 evolve next turn.\'};\n  if(a.plot===\'hit\' && !c._tookHit) return {ok:false,why:\'Plot Point 1 not met \\u2014 \'+c.name+\' hasn\\u2019t taken damage yet.\'};\n  if(a.plot===\'climaxQ\' && c._gateSpent===actTurnKey()) return {ok:false,why:\'The climax attempt is spent for this turn.\'};\n  return {ok:true};\n}\nfunction actTargets(p,a){ return (p.team||[]).filter(function(c){ return c.hp>0 && actBaseOk(c) && actStageId(c)===a.from; }); }\nfunction actPick(p,card){\n  const a=actById(card&&card.actId); if(!a) return {a:null,t:null,why:\'Unknown Act card.\'};\n  const tg=actTargets(p,a);\n  if(!tg.length) return {a,t:null,why:a.name+\' evolves from \'+actStageName(a.from)+\' \\u2014 none on your field.\'};\n  const ok=tg.filter(function(c){ return actCanEvolve(c,a).ok; });\n  if(!ok.length) return {a,t:null,why:actCanEvolve(tg[0],a).why};\n  const act=active(p);\n  return {a,t:(ok.indexOf(act)>=0?act:ok[0]),why:\'\'};\n}\nfunction actPlayable(p,card){ return !!actPick(p,card).t; }\nfunction actEvolve(side,handIdx,c){\n  const p=S[side], card=p.hand[handIdx], a=actById(card&&card.actId); if(!a||!c) return false;\n  const taken=Math.max(0,c.maxHp-c.hp), from=c.name;\n  if(!c._actBase) c._actBase={ name:c.name, maxHp:c.maxHp, atk:clone(c.atk), blk:clone(c.blk), atk2:c.atk2?clone(c.atk2):null,\n    img:c.img||\'\', imgpos:c.imgpos||\'\', accent:c.accent, archetype:c.archetype, tags:c.tags?clone(c.tags):null, passive:c.passive?clone(c.passive):null };\n  p.hand.splice(handIdx,1);\n  (c._actCards=c._actCards||[]).push(card);\n  const scale=(S.settings&&S.settings.hpScale)||1;\n  const mx=Math.max(10, Math.round(a.hp*scale/10)*10);\n  c.name=a.name; c.maxHp=mx; c.hp=Math.max(1, mx-taken);\n  c.atk=clone(a.atk); c.blk=clone(a.blk); delete c.atk2; if(a.atk2) c.atk2=clone(a.atk2);\n  if(a.img){ c.img=a.img; c.imgpos=a.imgpos||\'50% 18%\'; }\n  if(a.accent) c.accent=a.accent; if(a.archetype) c.archetype=a.archetype; if(a.tags) c.tags=clone(a.tags);\n  if(a.passive) c.passive=clone(a.passive); else delete c.passive;\n  c.act=a.act; c._actId=a.id; c.resolution=a.resolution||null;\n  clearAllStatus(c);\n  c.turnsInPlay=0; c._tookHit=false; c._evoFx=true;\n  pushLog(`\\u2605 ${from} evolves into ${a.name} (Act ${roman(a.act)}) \\u2014 ${taken} damage and ${c.atkCharge.length+c.blkCharge.length} charge${(c.atkCharge.length+c.blkCharge.length)===1?\'\':\'s\'} carried over.`);\n  try{ SFX.card(\'book_flip\',0.7); }catch(e){}\n  return true;\n}\nfunction actGatePick(deck){\n  S._actGateUsed=S._actGateUsed||[];\n  let pool=((DATA.actGate&&DATA.actGate[deck])||[]).map(function(q){ return {tag:q.tag||\'theme\',q:q.q,opts:q.opts,ans:q.ans}; });\n  if(!pool.length) pool=(DATA.abcs[deck]||[]).map(function(q){ return {tag:\'story\',q:q.q,opts:q.opts,ans:q.ans}; });\n  let fresh=pool.filter(function(q){ return S._actGateUsed.indexOf(q.q)<0; });\n  if(!fresh.length){ S._actGateUsed=[]; fresh=pool; }\n  const q=fresh.length?fresh[rnd(fresh.length)]:null; if(q) S._actGateUsed.push(q.q); return q;\n}\nfunction actPlay(side,idx){\n  const p=S[side], card=p.hand[idx]; if(!card||card.cat!==\'act\') return false;\n  const pk=actPick(p,card);\n  if(!pk.t){ if(side===\'you\') toast(pk.why,\'bad\'); return false; }\n  if(pk.a.plot===\'climaxQ\'){\n    const q=actGatePick(pk.a.deck);\n    if(q){\n      if(side===\'you\'){ busy=true; S._actGate={cid:card.cid, uid:pk.t.uid, q:q, picked:null}; try{ SFX.card(\'book_flip\',0.7); }catch(e){} render(); return true; }\n      if(Math.random()>=((S.settings&&S.settings.aiAccuracy!=null)?S.settings.aiAccuracy:0.8)){\n        pk.t._gateSpent=actTurnKey(); pushLog(`Opponent misses the climax question \\u2014 ${pk.a.name} stays in hand.`); return false; }\n    }\n  }\n  actEvolve(side,idx,pk.t); render(); return true;\n}\nfunction actAnswer(i){\n  const g=S&&S._actGate; if(!g||g.picked!=null) return;\n  g.picked=i;\n  const p=S.you, idx=p.hand.findIndex(function(c){ return c.cid===g.cid; }), t=p.team.find(function(c){ return c.uid===g.uid; });\n  if(i===g.q.ans && idx>=0 && t){ const nm=(actById(p.hand[idx].actId)||{}).name||\'Act III\';\n    actEvolve(\'you\',idx,t); S._actGate=null; busy=false; toast(\'Climax reached \\u2014 \'+nm,\'good\'); render(); return; }\n  if(t) t._gateSpent=actTurnKey();\n  pushLog(\'Climax question missed \\u2014 the Act card returns to hand. No further attempt this turn.\');\n  render();\n}\nfunction actGateClose(){ if(!S) return; S._actGate=null; busy=false; render(); }\nfunction actGateModal(){\n  const g=S._actGate; if(!g||!g.q) return \'\';\n  const q=g.q, wrong=g.picked!=null && g.picked!==q.ans;\n  const opts=q.opts.map(function(o,i){ const cls=g.picked==null?\'\':(i===q.ans?\' gate-right\':(i===g.picked?\' gate-wrong\':\'\'));\n    return `<button class="tri-opt${cls}" data-do="actans:${i}"${g.picked!=null?\' disabled\':\'\'}><b>${\'ABCD\'[i]}</b> ${o}</button>`; }).join(\'\');\n  return `<div class="modal-bg"><div class="trivia climax">\n    <div class="tri-head">\\u2726 ACT III \\u00b7 THE CLIMAX</div>\n    <div class="tri-sub${wrong?\' tri-retry\':\'\'}">${wrong?\'Not this time \\u2014 the card returns to hand.\':\'Answer correctly to reach Act III. No retry.\'}<span class="gate-tag ${q.tag}">${String(q.tag).toUpperCase()}</span></div>\n    <div class="tri-q">${q.q}</div>\n    <div class="tri-opts">${opts}</div>\n    ${wrong?\'<div class="gate-foot"><button class="tri-opt" data-do="actclose">Return card to hand</button></div>\':\'\'}</div></div>`;\n}\n/* KO: the whole stack goes to the discard and the Act I card rests in the\n   grave, so every revive path (Deus Ex Machina, Adaptation, Defibrillator)\n   brings back Act I without needing its own guard. */\nfunction actOnKO(p,c){\n  if(!c||!c._actBase) return;\n  const b=c._actBase, top=c.name;\n  (c._actCards||[]).forEach(function(x){ p.discard.push(x); }); c._actCards=[];\n  c.name=b.name; c.maxHp=b.maxHp; c.atk=b.atk; c.blk=b.blk; if(b.atk2) c.atk2=b.atk2; else delete c.atk2;\n  c.img=b.img; c.imgpos=b.imgpos; c.accent=b.accent; c.archetype=b.archetype;\n  if(b.tags) c.tags=b.tags; else delete c.tags;\n  if(b.passive) c.passive=b.passive; else delete c.passive;\n  delete c.act; delete c._actId; delete c.resolution; delete c._actBase; delete c._evoFx; delete c._gateSpent;\n  pushLog(`${top}\\u2019s Act cards go to the discard; ${c.name} rests with the fallen.`);\n}\n/* deck building: the Act I base of every line in the deck is guaranteed a\n   place on the Classic team, or its Act cards would sit dead in the deck */\nfunction actLegal(acts,ch){\n  let out=(acts||[]).slice(), changed=true;\n  while(changed){ changed=false;\n    out=out.filter(function(id){ const a=actById(id); if(!a) { changed=true; return false; }\n      const ok = a.act===2 ? (ch||[]).indexOf(a.from)>=0 : out.indexOf(a.from)>=0;\n      if(!ok) changed=true; return ok; }); }\n  return out;\n}\nfunction actStarter(def){\n  if(!def||!def.d) return def;\n  const acts=actsForDeck(def.d).filter(function(a){ return (def.ch||[]).indexOf(a.base[1])>=0; }).map(function(a){ return a.id; });\n  const legal=actLegal(acts,def.ch); if(!legal.length) return def;\n  const cap=(typeof compFor===\'function\'?(compFor(def.d)||{}).ch:null)||LIMITS.ch;\n  const keep=new Set(legal.map(function(id){ return actById(id).base[1]; }));\n  while(def.ch.length+legal.length>cap){ let i=def.ch.length-1; while(i>=0 && keep.has(def.ch[i])) i--; if(i<0) break; def.ch.splice(i,1); }\n  def.act=legal; return def;\n}\nfunction actFrontLoad(pool,def){\n  const bases=new Set((def.act||[]).map(function(id){ const a=actById(id); return a?a.base[1]:null; }).filter(Boolean));\n  if(!bases.size) return pool;\n  pool.sort(function(x,y){ return (bases.has(y.id)?1:0)-(bases.has(x.id)?1:0); });\n  return pool;\n}\nfunction actAiTurn(p){\n  let guard=0;\n  for(;;){ if(guard++>4||!S||S.over) return;\n    const i=p.hand.findIndex(function(c){ return c.cat===\'act\' && actPlayable(p,c); });\n    if(i<0) return;\n    const card=p.hand[i];\n    if(actPlay(\'opp\',i)){ try{ zoomCard(\'opp\', zoomHtmlFor(card), 2200); }catch(e){} }\n  }\n}\nif(typeof window!==\'undefined\') window.ABC_ACT={ actById, actsForDeck, actCanEvolve, actPick, actPlayable, actEvolve, actPlay, actAnswer, actGateClose, actOnKO, actLegal, actStarter, actAiTurn, actGatePick };\n'
EDITS=[('engine block', '/* ---------------- 1st Edition (Commander) passive engine ---------------- */', '__ENGINE__\n/* ---------------- 1st Edition (Commander) passive engine ---------------- */'), ('makeDeck: Act cards', '  return shuffle(deck);\n}\nfunction newPlayer(', "  (def.act||[]).forEach(function(id,n){ const a=actById(id); if(a) deck.push({cat:'act', actId:id, name:a.name, act:a.act, deck:a.deck, cid:'act'+n+'_'+Math.random().toString(36).slice(2,6)}); });\n  return shuffle(deck);\n}\nfunction newPlayer("), ('newPlayer: line bases on team', '  const pool=shuffle(clone(defs));\n', '  const pool=actFrontLoad(shuffle(clone(defs)),def);\n'), ('defaultDeck: starter line', '  return fillGaps(def, c);\n}', '  return actStarter(fillGaps(def, c));\n}'), ('clampDeck: validate acts', '  def.ch=(def.ch||[]).filter(id=>_chOk.has(id)).slice(0,_CAP.ch);\n', '  def.ch=(def.ch||[]).filter(id=>_chOk.has(id)).slice(0,_CAP.ch);\n  /* Act cards: own book only, a legal line only, and inside the character limit */\n  def.act=actLegal((def.act||[]).filter(function(id){ const a=actById(id); return a && _bks.indexOf(a.deck)>=0; }), def.ch);\n  if(def.ch.length+def.act.length>_CAP.ch) def.act=actLegal(def.act.slice(0,Math.max(0,_CAP.ch-def.ch.length)), def.ch);\n'), ('encodeDeck', '  try{ const j=JSON.stringify({d:def.d,ch:def.ch,ab:def.ab,bm:def.bm,cr:def.cr,fe:def.fe||[]});', '  try{ const j=JSON.stringify({d:def.d,ch:def.ch,ab:def.ab,bm:def.bm,cr:def.cr,fe:def.fe||[],act:def.act||[]});'), ('decodeDeck', '    return clampDeck({d:o.d,ch:o.ch||[],ab:o.ab||[],bm:o.bm||[],cr:o.cr||[],fe:o.fe||[]});', '    return clampDeck({d:o.d,ch:o.ch||[],ab:o.ab||[],bm:o.bm||[],cr:o.cr||[],fe:o.fe||[],act:o.act||[]});'), ('pmEncodeDeck', '      ch:def.ch, ab:def.ab, bm:def.bm, cr:def.cr, fe:def.fe||[] });', '      ch:def.ch, ab:def.ab, bm:def.bm, cr:def.cr, fe:def.fe||[], act:def.act||[] });'), ('pmDecodeDeck', '             ch:o.ch||[], ab:o.ab||[], bm:o.bm||[], cr:o.cr||[], fe:o.fe||[],', '             ch:o.ch||[], ab:o.ab||[], bm:o.bm||[], cr:o.cr||[], fe:o.fe||[], act:o.act||[],'), ('tryPlayHandCard: route Act cards', "  if(drawnLocked()){ toast('Place a character as your Active first.'); return; }\n", "  if(drawnLocked()){ toast('Place a character as your Active first.'); return; }\n  if(card.cat==='act'){ actPlay('you',idx); return; }\n"), ('applyDmg: Plot Point 1', '  c.hp=Math.max(0,c.hp-d);\n', '  c.hp=Math.max(0,c.hp-d);\n  if(d>0) c._tookHit=true;\n'), ('healChar: noHeal on Act passives', 'if(c.fe && c.passive && c.passive.noHeal)', 'if((c.fe||c.act>1) && c.passive && c.passive.noHeal)'), ('attack: lowHpAtkAdd', '  if(att.fe&&att.passive&&att.passive.soloBonus&&isSoloAlive(A))', '  if(att.act>1&&att.passive&&att.passive.lowHpAtkAdd&&att.hp>0&&att.hp<att.maxHp/2){ dmg+=att.passive.lowHpAtkAdd; pushLog(`${att.passive.name||att.name}: +${att.passive.lowHpAtkAdd} damage below half health.`); }\n  if(att.fe&&att.passive&&att.passive.soloBonus&&isSoloAlive(A))'), ('checkKO: stack to discard', "      if(hasCrit(side,'adapt') && _succ && _succ.hp>0){ try{ adaptInherit(p,side,_fallen,_succ); }catch(e){} } }\n", "      if(hasCrit(side,'adapt') && _succ && _succ.hp>0){ try{ adaptInherit(p,side,_fallen,_succ); }catch(e){} } }\n    actOnKO(p,a);\n"), ('zoom preview for Act cards', '    if(card.fe) return buildFePreview(card);\n', "    if(card.cat==='act'){ const _a=actById(card.actId); return _a?buildCharPreview(_a,_a.deck):''; }\n    if(card.fe) return buildFePreview(card);\n"), ('gate modal in render chain', "${S.pending?triviaModal():''}", "${S.pending?triviaModal():''}${S._actGate?actGateModal():''}"), ('click: gate answers', "    else if(d==='dmflipall') drawnFlipAll();\n", "    else if(d.indexOf('actans:')===0){ actAnswer(+d.slice(7)); }\n    else if(d==='actclose'){ actGateClose(); }\n    else if(d==='dmflipall') drawnFlipAll();\n"), ('AI: evolve before the bookmark brain', '    const prof=aiProfile();\n', '    try{ actAiTurn(p); }catch(e){}\n    const prof=aiProfile();\n')]
def die(m): sys.exit("[fix_act_2_engine] ABORT: "+m)
if not os.path.exists(SRC): die(SRC+" not found -- run from the repo root")
s=open(SRC,encoding="utf-8").read()
if MARK in s: die("already applied")
if "/* THREE-ACT EVOLUTION: DATA */" not in s: die("run fix_act_1_data.py first")
for label,a,r in EDITS:
    n=s.count(a)
    if n!=1: die("anchor for '%s' found %d times (need 1)"%(label,n))
shutil.copyfile(SRC,SRC+".bak")
for label,a,r in EDITS:
    s=s.replace(a,r.replace("__ENGINE__",ENGINE),1)
open(SRC,"w",encoding="utf-8").write(s)
print("[fix_act_2_engine] OK -- %d edits applied"%len(EDITS))
